mapper.select:
select *
from (select a.*, rank() over (partition by product_code order by create_time desc ,id desc ) as xh
from ${dynamicTableNameProxy.getProductPriceFollow(enterpriseCode)} a
where create_time >= CURRENT_DATE - INTERVAL '8 days'
and delete_flag = false
and product_code in

    #{id}

and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
)
where xh = 1
